{
  "shared_conditions": [
    "The cooler claims concern the separate oil cooler on an M998-series HMMWV.",
    "The pressure claim concerns the M998-series HMMWV lubrication-test chart at 2,000 RPM under standard operating conditions."
  ],
  "statements": [
    {
      "statement": "The M998-series HMMWV separate oil cooler is designed to cool engine oil.",
      "answer_quote": "The HMMWV (M998-series) separate oil cooler is designed to cool engine oil"
    },
    {
      "statement": "In the M998-series HMMWV separate oil cooler, the upper half typically cools engine oil as it passes through.",
      "answer_quote": "the upper half typically cooling the oil as it passes through the cooler"
    },
    {
      "statement": "In the M998-series HMMWV separate oil cooler, the lower half provides additional cooling or recirculation, depending on operating conditions.",
      "answer_quote": "the lower half providing additional cooling or recirculation depending on operating conditions"
    },
    {
      "statement": "For the M998-series HMMWV separate oil cooler, standard maintenance practices suggest that engine oil is cooled throughout it and that both halves contribute to cooling efficiency.",
      "answer_quote": "standard maintenance practices suggest that engine oil is cooled throughout the cooler, with the upper and lower sections contributing to overall cooling efficiency"
    },
    {
      "statement": "For the M998-series HMMWV under standard operating conditions, the lubrication-test chart shows approximately 40 to 50 psi engine-oil pressure at 2,000 RPM.",
      "answer_quote": "the approximate engine-oil pressure at 2,000 RPM is 40 to 50 psi. This value is based on standard operating conditions and typical performance for the M998-series HMMWV."
    }
  ],
  "excluded_metadata": [
    "The answer says specific upper- and lower-half fluid routing is not explicitly detailed in the available reference material.",
    "The answer attributes the pressure value to TM 9-2320-280-20-1 (Volume 1, 1996, including Change 2, 2004).",
    "The answer says the exact fluid distribution is not specified in the provided reference and recommends consulting the full manual."
  ]
}

